algorithms.pseudocode:
Input: valuation v, seed set S, domain D
1. Compute V = {v(s) : s in S}
2. Return {x in D : v(x) in V}
Complexity: O(|S| + |D|)

algorithms.code:
def level_set_closure(v, seed, domain):
    val_image = {v(s) for s in seed}
    return {x for x in domain if v(x) in val_image}

def are_closure_equivalent(v1, v2, domain):
    def partition(v):
        groups = {}
        for x in domain:
            groups.setdefault(v(x), set()).add(x)
        return set(frozenset(g) for g in groups.values())
    return partition(v1) == partition(v2)

def find_separating_threshold(v, x, y):
    vx, vy = v(x), v(y)
    assert vx != vy
    return min(vx, vy)
